using System.Reflection;
using Microsoft.Extensions.DependencyInjection;

namespace Core.Application.BusinessStrategy;

public static class DependencyInjection
{
    public static void AddBusinessStrategies(this IServiceCollection services)
    {
        // Adds the BusinessStrategySelector as a scoped service, allowing it to be injected where needed.
        services.AddScoped(typeof(BusinessStrategySelector<,>));

        // Adds all BusinessStrategies as scoped services, keyed by the context they are associated with.
        var applicationAssembly = typeof(IBusinessStrategy<,>).Assembly;
        var businessStrategyTypes = applicationAssembly.GetTypes()
            .Where(t => t.GetCustomAttribute<BusinessStrategyAttribute>() != null &&
                        t is { IsAbstract: false, IsInterface: false });

        foreach (var strategyType in businessStrategyTypes)
        {
            var attribute = strategyType.GetCustomAttribute<BusinessStrategyAttribute>();
            if (attribute is null)
            {
                continue;
            }

            var contextKey = attribute.Context;

            var businessStrategyInterface = strategyType.GetInterfaces()
                .FirstOrDefault(i => i.IsGenericType && i.GetGenericTypeDefinition() == typeof(IBusinessStrategy<,>));

            if (businessStrategyInterface is not null)
            {
                services.AddKeyedScoped(businessStrategyInterface, contextKey, strategyType);
            }
        }
    }
}

using System.Reflection;
using Microsoft.Extensions.DependencyInjection;

namespace Core.Application.BusinessStrategy;

public static class DependencyInjection
{
    public static void AddBusinessStrategies(this IServiceCollection services)
    {
        services.AddBusinessStrategiesFromAssembly(typeof(IBusinessStrategy<,>).Assembly);
    }

    public static void AddBusinessStrategiesFromAssembly(
        this IServiceCollection services,
        Assembly assembly,
        string? namespacePrefix = null)
    {
        services.AddScoped(typeof(BusinessStrategySelector<,>));

        var businessStrategyTypes = assembly.GetTypes()
            .Where(t => t.GetCustomAttribute<BusinessStrategyAttribute>() != null)
            .Where(t => t is { IsAbstract: false, IsInterface: false })
            .Where(t => namespacePrefix is null || (t.Namespace?.StartsWith(namespacePrefix, StringComparison.Ordinal) ?? false));

        foreach (var strategyType in businessStrategyTypes)
        {
            var attribute = strategyType.GetCustomAttribute<BusinessStrategyAttribute>();
            if (attribute is null)
            {
                continue;
            }

            var contextKey = attribute.Context;

            var strategyInterfaces = strategyType.GetInterfaces()
                .Where(i => i.IsGenericType && i.GetGenericTypeDefinition() == typeof(IBusinessStrategy<,>));

            foreach (var strategyInterface in strategyInterfaces)
            {
                services.AddKeyedScoped(strategyInterface, contextKey, strategyType);
            }
        }
    }
}

using Core.Application.Dispatcher;
using Core.Application.Features.Products;
using Microsoft.Extensions.DependencyInjection;

namespace Core.Application;

public static class DependencyInjection
{
    public static void AddCommandAndQueryHandlers(this IServiceCollection services)
    {
        var commandHandlers = typeof(GetProductHandler).Assembly.GetTypes()
            .Where(t => t.GetInterfaces().Any(i =>
                i.IsGenericType && i.GetGenericTypeDefinition() == typeof(ICommandHandler<,>)));

        foreach (var handler in commandHandlers)
        {
            var interfaceType = handler.GetInterfaces().First(i =>
                i.IsGenericType && i.GetGenericTypeDefinition() == typeof(ICommandHandler<,>));
            services.AddScoped(interfaceType, handler);
        }

        var queryHandlers = typeof(GetProductHandler).Assembly.GetTypes()
            .Where(t => t.GetInterfaces().Any(i =>
                i.IsGenericType && i.GetGenericTypeDefinition() == typeof(IQueryHandler<,>)));

        foreach (var handler in queryHandlers)
        {
            var interfaceType = handler.GetInterfaces().First(i =>
                i.IsGenericType && i.GetGenericTypeDefinition() == typeof(IQueryHandler<,>));
            services.AddScoped(interfaceType, handler);
        }

        services.AddScoped<InternalDispatcher>();
    }
}

using System.Reflection;
using Core.Application.Dispatcher;
using Microsoft.Extensions.DependencyInjection;

namespace Core.Application;

public static class DependencyInjection
{
    public static void AddCommandAndQueryHandlers(this IServiceCollection services)
    {
        services.AddCommandAndQueryHandlersFromAssembly(typeof(DependencyInjection).Assembly);
    }

    public static void AddCommandAndQueryHandlersFromAssembly(
        this IServiceCollection services,
        Assembly assembly,
        string? namespacePrefix = null)
    {
        var concreteTypes = assembly.GetTypes()
            .Where(t => t is { IsAbstract: false, IsInterface: false })
            .Where(t => namespacePrefix is null || (t.Namespace?.StartsWith(namespacePrefix, StringComparison.Ordinal) ?? false));

        RegisterHandlers(services, concreteTypes, typeof(ICommandHandler<,>));
        RegisterHandlers(services, concreteTypes, typeof(IQueryHandler<,>));

        services.AddScoped<InternalDispatcher>();
    }

    private static void RegisterHandlers(
        IServiceCollection services,
        IEnumerable<Type> concreteTypes,
        Type openGenericHandlerType)
    {
        foreach (var implementationType in concreteTypes)
        {
            var serviceInterfaces = implementationType.GetInterfaces()
                .Where(i => i.IsGenericType && i.GetGenericTypeDefinition() == openGenericHandlerType);

            foreach (var serviceType in serviceInterfaces)
            {
                services.AddScoped(serviceType, implementationType);
            }
        }
    }
}

using Core.Application.Features.Authentication;
using Microsoft.Extensions.DependencyInjection;

namespace Infrastructure.Features.Authentication;

public static class DependencyInjection
{
    public static IServiceCollection AddAuthenticationInfrastructure(this IServiceCollection services)
    {
        services.AddSingleton<IIdentityService, FakeIdentityService>();
        return services;
    }
}

using Core.Application.Features.Products;
using Microsoft.Extensions.DependencyInjection;

namespace Infrastructure.Features.Products;

public static class DependencyInjection
{
    public static IServiceCollection AddProductsInfrastructure(this IServiceCollection services)
    {
        services.AddKeyedSingleton<IProductRepository, RealProductRepository>(ProductStrategies.Real);
        services.AddKeyedSingleton<IProductRepository, FakeProductRepository>(ProductStrategies.Fake);
        services.AddSingleton<IProductRepository, RealProductRepository>();
        return services;
    }
}

namespace Modules.Authentication.Application;

public record AuthenticationResult(
    string? AccessToken,
    string? TokenType,
    int? ExpiresIn,
    string? RefreshToken)
{
    public static AuthenticationResult Empty => new(null, null, null, null);
}

namespace Modules.Authentication.Application;

public interface IIdentityService
{
    Task<AuthenticationResult> AuthenticateAsync(string email, string password);
    Task<AuthenticationResult> RotateTokenAsync(string refreshToken);
}

using Core.Application.Dispatcher;

namespace Modules.Authentication.Application;

public record LoginCommand(string Email, string Password) : ICommand<AuthenticationResult>;

using Core.Application.Dispatcher;

namespace Modules.Authentication.Application;

public class LoginCommandHandler(IIdentityService identityService) : ICommandHandler<LoginCommand, AuthenticationResult>
{
    public Task<AuthenticationResult> HandleAsync(LoginCommand command)
    {
        return identityService.AuthenticateAsync(command.Email, command.Password);
    }
}

using Core.Application.Dispatcher;

namespace Modules.Authentication.Application;

public record RefreshTokenCommand(string RefreshToken) : ICommand<AuthenticationResult>;

using Core.Application.Dispatcher;

namespace Modules.Authentication.Application;

public class RefreshTokenCommandHandler(IIdentityService identityService) : ICommandHandler<RefreshTokenCommand, AuthenticationResult>
{
    public Task<AuthenticationResult> HandleAsync(RefreshTokenCommand command)
    {
        return identityService.RotateTokenAsync(command.RefreshToken);
    }
}

using Core.Application.Dispatcher;
using Modules.Products.Domain;

namespace Modules.Products.Application;

public record CreateProductCommand(
    string Name,
    string Description,
    decimal Price,
    Guid CategoryId
) : ICommand<Product>;

using Core.Application.Dispatcher;
using Modules.Products.Domain;

namespace Modules.Products.Application;

public class CreateProductHandler(IProductRepository productRepository) : ICommandHandler<CreateProductCommand, Product>
{
    public Task<Product> HandleAsync(CreateProductCommand command)
    {
        return productRepository.CreateProduct(new Product(
            command.Name,
            command.Description,
            command.Price,
            command.CategoryId
        ));
    }
}

using Core.Application.BusinessStrategy;
using Microsoft.Extensions.DependencyInjection;
using Modules.Products.Domain;

namespace Modules.Products.Application;

[BusinessStrategy(ProductStrategies.Fake)]
public sealed class GetProductFromFakeRepositoryStrategy(IServiceProvider serviceProvider)
    : IBusinessStrategy<GetProductQuery, Product?>
{
    public bool CanHandle(GetProductQuery request)
        => string.Equals(request.Source, ProductStrategies.Fake, StringComparison.OrdinalIgnoreCase);

    public Task<Product?> ExecuteAsync(GetProductQuery request, CancellationToken cancellationToken = default)
        => serviceProvider.GetRequiredKeyedService<IProductRepository>(ProductStrategies.Fake)
            .GetProduct(request.ProductId);
}

using Core.Application.BusinessStrategy;
using Microsoft.Extensions.DependencyInjection;
using Modules.Products.Domain;

namespace Modules.Products.Application;

[BusinessStrategy(ProductStrategies.Real)]
public sealed class GetProductFromRealRepositoryStrategy(IServiceProvider serviceProvider)
    : IBusinessStrategy<GetProductQuery, Product?>
{
    public bool CanHandle(GetProductQuery request)
        => string.Equals(request.Source, ProductStrategies.Real, StringComparison.OrdinalIgnoreCase);

    public Task<Product?> ExecuteAsync(GetProductQuery request, CancellationToken cancellationToken = default)
        => serviceProvider.GetRequiredKeyedService<IProductRepository>(ProductStrategies.Real)
            .GetProduct(request.ProductId);
}

using Core.Application.BusinessStrategy;
using Core.Application.Dispatcher;
using Modules.Products.Domain;

namespace Modules.Products.Application;

public class GetProductHandler(BusinessStrategySelector<GetProductQuery, Product?> selector)
    : IQueryHandler<GetProductQuery, Product?>
{
    public Task<Product?> HandleAsync(GetProductQuery query)
    {
        return selector.SelectAndExecuteAsync(query);
    }
}

using Core.Application.BusinessStrategy;
using Core.Application.Dispatcher;
using Modules.Products.Domain;

namespace Modules.Products.Application;

public record GetProductQuery(Guid ProductId, string Source = ProductStrategies.Fake)
    : IQuery<Product?>, IBusinessStrategyRequest
{
    public string StrategyContext => Source;
}

using Modules.Products.Domain;

namespace Modules.Products.Application;

public interface IProductRepository
{
    Task<Product?> GetProduct(Guid id);
    Task<Product> CreateProduct(Product product);
}

namespace Modules.Products.Application;

public static class ProductStrategies
{
    public const string Real = "real";
    public const string Fake = "fake";
}

namespace Modules.Products.Domain;

public record Product(
    string Name,
    string Description,
    decimal Price,
    Guid CategoryId
);
